  (function() {
    // 1. Obtenemos el tipo de base de datos del nodo de configuración
    const dbType = $('Setear Datos').first().json.DataBaseType;

    // 2. Obtenemos la URL Base (tomada del nodo 'RefresSessionID' según tu imagen)
    const baseUrl = $('RefresSessionID').item.json.URLSL; 

    // 3. Obtenemos el nombre de la vista y el ID del documento dinámicamente
    // (Puedes cambiar "\(('Split Out').item.json" por "\)json" si este nodo está directamente conectado)
    const vistaLayout = $json.VistaLayout; 
    const entry = $json.DocEntry; 

    // 4. Construimos la URL
    if (dbType === 'SQL') {
      // Endpoint para SQL Server (filtrando por OData)
      return baseUrl + "/b1s/v2/view.svc/" + vistaLayout + "?$filter=DocEntry eq " + entry;

      /* Nota: Si Service Layer te arroja un error de tipado en SQL, 
         ponle comillas simples al entry descomentando la siguiente línea y borrando la anterior:
         return baseUrl + "/b1s/v2/view.svc/" + vistaLayout + "?$filter=DocEntry eq '" + entry + "'";
      */
    } else {
      // Endpoint para HANA (usando parámetros directos como en tu imagen)
      return baseUrl + "/b1s/v2/sml.svc/" + vistaLayout + "Parameters(Entry=" + entry + ")/" + vistaLayout;
    }
  })()
}}

