const items = $input.all();

function formatMoney(valor, opciones = {}) {
  const { conSimbolo = false, simbolo = '$' } = opciones;
  const num = Number(valor);
  if (valor === null || valor === undefined || isNaN(num)) {
    return conSimbolo ? `${simbolo} 0` : '0';
  }
  return conSimbolo
    ? `${simbolo} ${num.toLocaleString('es-CO', { minimumFractionDigits: 0, maximumFractionDigits: 2 })}`
    : num.toLocaleString('es-CO', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}

// Convierte null/undefined en cadena vacía para evitar el texto "null" en el HTML
function limpio(valor) {
  return (valor === null || valor === undefined) ? '' : valor;
}

let filasHTML = "";

for (const item of items) {
  const art = item.json;
  filasHTML += `
    <tr>
      <td>${art.CodigoArticulo || ''}</td>
      <td class="desc-cell">${art.DescripcionArticulo || ''}</td>
      <td>${art.NombreUnidadMedida || ''}</td>
      <td class="number-cell">${art.Cantidad || 0}</td>
      <td class="number-cell">${formatMoney(art.PrecioUnitario)}</td>
      <td class="number-cell">${formatMoney(art.TotalLinea)}</td>
    </tr>
  `;
}

let cabecera = items[0].json;
cabecera.FilasTabla = filasHTML;

// Calcular SubTotal si SAP no lo provee directamente (con los valores numéricos crudos, antes de formatear)
if (!cabecera.SubTotal && cabecera.TotalDocumento && cabecera.TotalIVA) {
  cabecera.SubTotal = cabecera.TotalDocumento - cabecera.TotalIVA;
}

// Formatear los campos monetarios de cabecera (se hace DESPUÉS del cálculo de SubTotal)
cabecera.SubTotal        = formatMoney(cabecera.SubTotal);
cabecera.TotalIVA        = formatMoney(cabecera.TotalIVA);
cabecera.TotalDocumento  = formatMoney(cabecera.TotalDocumento);

// Sanear campos que pueden venir null y romper el texto de la dirección o el contacto
cabecera.NombreContacto   = limpio(cabecera.NombreContacto);
cabecera.CiudadProveedor  = limpio(cabecera.CiudadProveedor);
cabecera.ReferenciaProveedor = limpio(cabecera.ReferenciaProveedor);

// Arma la dirección completa evitando guiones o comas huérfanas cuando faltan datos
const partesDireccion = [
  cabecera.DireccionProveedor,
  cabecera.CiudadProveedor,
  cabecera.PaisProveedor
].filter(p => p && p.trim() !== '');

cabecera.DireccionProveedorCompleta = partesDireccion.join(', ');

function renderTemplate(template, data) {
  if (!template) return '';
  const dataLower = {};
  for (const key in data) {
    dataLower[key.toLowerCase()] = data[key];
  }
  return template.replace(/%%(\w+)%%/g, (match, campo) => {
    const valor = dataLower[campo.toLowerCase()];
    return (valor !== undefined && valor !== null) ? valor : '';
  });
}

return [{ json: cabecera }];

