const items = $input.all();

function formatMoney(valor, opciones = {}) {
  const { conSimbolo = false, simbolo = '$' } = opciones;
  const num = Number(valor);
  if (valor === null || valor === undefined || isNaN(num)) {
    return conSimbolo ? `${simbolo} 0` : '0';
  }
  return conSimbolo
    ? `${simbolo} ${num.toLocaleString('es-CO', { minimumFractionDigits: 0, maximumFractionDigits: 2 })}`
    : num.toLocaleString('es-CO', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}

let filasHTML = "";

// Acumuladores para los totales del documento
let sumaTotalAntesDcto = 0;
let sumaDescuento  = 0;

for (const item of items) {
  const det = item.json;

  // Sumar los valores de línea (numéricos, antes de formatear)
  sumaTotalAntesDcto += Number(det.TotalAntesDcto) || 0;
  sumaDescuento  += Number(det.SumaDescuento) || 0;

  filasHTML += `
    <tr>
      <td>${det.DocNumPagado || ''}</td>
      <td class="number-cell">${formatMoney(det.ValorAplicado)}</td>
      <td class="number-cell">${formatMoney(det.SumaDescuento)}</td>
      <td class="number-cell">${formatMoney(det.ValorRetencionIVA)}</td>
      <td class="number-cell">${formatMoney(det.ValorRetencionFTE)}</td>
      <td class="number-cell">${formatMoney(det.ValorRetencionICA)}</td>
      <td class="number-cell">${formatMoney(det.TotalAntesDcto)}</td>
    </tr>
  `;
}

let cabecera = items[0].json;
cabecera.FilasTablaPagos = filasHTML;

// TotalPago NO se suma: es un valor de cabecera repetido en cada línea, se toma tal cual
cabecera.TotalPago = formatMoney(cabecera.TotalPago);

// Estos SÍ son sumas acumuladas de todas las líneas
cabecera.TotalAntesDcto     = formatMoney(sumaTotalAntesDcto);
cabecera.SumaDescuento     = formatMoney(sumaDescuento);

cabecera.ValorTransferencia = formatMoney(cabecera.ValorTransferencia);

cabecera.Comentarios = cabecera.Comentarios ? cabecera.Comentarios : '';

return [{ json: cabecera }];

// Obtenemos los valores desde el nodo Filter (que contiene la misma data del Switch)
const tipoDoc = $('Filter').item.json.TipoDoc;
const docNum = $('Filter').item.json.DocNum;

// Asignamos el nuevo nombre dinámico al archivo adjunto
$input.item.binary.data.fileName = `${tipoDoc} - ${docNum}.pdf`;

return $input.item;
